    12→// sourcery: AutoMockable
    13→protocol RoomMemberProxyProtocol: AnyObject {
    14→    var userID: String { get }
    15→    
    16→    var displayName: String? { get }
    17→    var disambiguatedDisplayName: String? { get }
    18→    
    19→    var avatarURL: URL? { get }
    20→    
    21→    var membership: MembershipState { get }
    22→    
    23→    var membershipChangeReason: String? { get }
    24→    
    25→    var isIgnored: Bool { get }
    26→    
    27→    var powerLevel: RoomPowerLevel { get }
    28→}
    29→
    30→extension RoomMemberProxyProtocol {
    31→    /// The member is active in the room (joined or invited).
    32→    var isActive: Bool {
    33→        membership == .join || membership == .invite || membership == .knock
    34→    }
    35→    
    36→    var permalink: URL? {
    37→        try? URL(string: matrixToUserPermalink(userId: userID))
    38→    }
    39→    
    40→    /// The name used for sorting the member alphabetically. This will be the displayname if,
    41→    /// it exists otherwise it will be the userID with the leading `@` removed.
    42→    var sortingName: String {
    43→        // If there isn't a displayname we sort by the userID without the @.
    44→        (displayName ?? String(userID.dropFirst())).lowercased()
    45→    }
    46→}
    47→
    48→extension [RoomMemberProxyProtocol] {
    49→    /// The members, sorted first by power-level, and then alphabetically within each power-level.
    50→    func sorted() -> Self {
    51→        sorted { lhs, rhs in
    52→            if lhs.powerLevel != rhs.powerLevel {
    53→                lhs.powerLevel > rhs.powerLevel
    54→            } else {
    55→                lhs.sortingName.localizedStandardCompare(rhs.sortingName) == .orderedAscending
    56→            }
    57→        }
