   342→    private func storeAndSubscribeToRoomProxy(_ roomProxy: JoinedRoomProxyProtocol) async {
   343→        if let oldRoomProxy = self.roomProxy {
   344→            if oldRoomProxy.id != roomProxy.id {
   345→                fatalError("Trying to create different room proxies for the same flow coordinator")
   346→            }
   347→            
   348→            MXLog.warning("Found an existing proxy, returning.")
   349→            return
   350→        }
   351→                
   352→        await roomProxy.subscribeForUpdates()
   353→        
   354→        // Make sure not to set this until after the subscription has succeeded, otherwise the
   355→        // early return above could result in trying to access the room's timeline provider
   356→        // before it has been set which triggers a fatal error.
   357→        self.roomProxy = roomProxy
   358→        
   359→        // Subscribe to room info updates in order to detect rooms being left on other devices
   360→        // and react accordingly by dismissing this flow coordinator.
   361→        self.roomProxy.infoPublisher
   362→            .receive(on: DispatchQueue.main)
   363→            .sink { [weak self] info in
   364→                guard let self else { return }
   365→                
   366→                if info.membership == .left || info.membership == .banned, stateMachine.state != .complete {
   367→                    stateMachine.tryEvent(.dismissFlow)
   368→                }
   369→            }
   370→            .store(in: &cancellables)
   371→    }
