    12→enum JoinRoomScreenViewModelAction {
    13→    case joined(JoinRoomScreenJoinDetails)
    14→    case dismiss
    15→    case presentDeclineAndBlock(userID: String)
    16→}
    17→
    18→enum JoinRoomScreenMode: Equatable {
    19→    case loading
    20→    case unknown
    21→    case joinable
    22→    case restricted
    23→    case inviteRequired
    24→    case invited(isDM: Bool)
    25→    case knockable
    26→    case knocked
    27→    case banned(sender: String?, reason: String?)
    28→    case forbidden
    29→    
    30→    var isInvite: Bool {
    31→        switch self {
    32→        case .invited:
    33→            true
    34→        default:
    35→            false
    36→        }
    37→    }
    38→}
    39→
    40→struct JoinRoomScreenRoomDetails {
    41→    let name: String?
    42→    let topic: String?
    43→    let canonicalAlias: String?
    44→    let avatar: RoomAvatar?
    45→    let memberCount: Int?
    46→    let heroes: [UserProfileProxy]
    47→    let inviter: RoomInviterDetails?
    48→    let isDirect: Bool?
    49→    
    50→    let isSpace: Bool?
    51→    let childrenCount: Int?
    52→    let spaceVisibility: SpaceServiceRoomVisibility?
    53→}
    54→
    55→struct JoinRoomScreenViewState: BindableState {
    56→    let roomID: String
    57→    
    58→    var roomDetails: JoinRoomScreenRoomDetails?
    59→    
    60→    var mode: JoinRoomScreenMode = .loading
    61→    
    62→    var hideInviteAvatars = false
    63→        
    64→    var bindings = JoinRoomScreenViewStateBindings()
    65→    
    66→    var shouldHideAvatars: Bool {
    67→        hideInviteAvatars && mode.isInvite
    68→    }
    69→    
    70→    var title: String {
    71→        if isDMInvite, let inviter = roomDetails?.inviter {
    72→            return inviter.displayName ?? inviter.id
    73→        } else {
    74→            return roomDetails?.name ?? L10n.screenJoinRoomTitleNoPreview
    75→        }
    76→    }
    77→    
    78→    var subtitle: String? {
    79→        if roomDetails?.isSpace == true, let spaceVisibilityTitle {
    80→            return spaceVisibilityTitle
    81→        } else {
    82→            switch mode {
    83→            case .invited(isDM: true):
    84→                if let inviter = roomDetails?.inviter {
    85→                    return inviter.displayName != nil ? inviter.id : nil
    86→                }
    87→                return nil
    88→            case .loading, .unknown, .knocked:
    89→                return nil
    90→            default:
    91→                return roomDetails?.canonicalAlias
    92→            }
    93→        }
    94→    }
    95→    
    96→    var subtitleIcon: KeyPath<CompoundIcons, Image>? {
    97→        guard roomDetails?.isSpace == true else { return nil }
    98→        
    99→        return switch roomDetails?.spaceVisibility {
   100→        case .public: \.public
   101→        case .private: \.lock
   102→        case .restricted: \.space
   103→        case .none: \.lock
   104→        }
   105→    }
   106→    
   107→    var spaceVisibilityTitle: String? {
   108→        switch roomDetails?.spaceVisibility {
   109→        case .public: L10n.commonPublicSpace
   110→        case .private: L10n.commonPrivateSpace
   111→        case .restricted: L10n.commonSharedSpace
   112→        case .none: L10n.commonPrivateSpace
   113→        }
   114→    }
   115→    
   116→    var avatar: RoomAvatar? {
   117→        // DM invites avatars are broken, this is a workaround
   118→        // https://github.com/matrix-org/matrix-rust-sdk/issues/4825
   119→        if isDMInvite, let inviter = roomDetails?.inviter {
   120→            .heroes([.init(userID: inviter.id, displayName: inviter.displayName, avatarURL: hideInviteAvatars ? nil : inviter.avatarURL)])
   121→        } else if let avatar = roomDetails?.avatar {
   122→            shouldHideAvatars ? avatar.removingAvatar : avatar
   123→        } else if let name = roomDetails?.name {
   124→            .room(id: roomID, name: name, avatarURL: nil)
   125→        } else {
   126→            nil
   127→        }
   128→    }
   129→    
   130→    var isDMInvite: Bool {
   131→        mode == .invited(isDM: true)
   132→    }
   133→}
   134→
   135→struct JoinRoomScreenViewStateBindings {
   136→    var alertInfo: AlertInfo<JoinRoomScreenAlertType>?
   137→    var knockMessage = ""
   138→}
   139→
   140→enum JoinRoomScreenAlertType {
   141→    case declineInvite
   142→    case declineInviteAndBlock
   143→    case cancelKnock
   144→    case loadingError
   145→    case invalidInvite
   146→}
   147→
   148→enum JoinRoomScreenViewAction {
   149→    case cancelKnock
   150→    case knock
   151→    case join
   152→    case acceptInvite
   153→    case declineInvite
   154→    case declineInviteAndBlock(userID: String)
   155→    case forget
   156→    case dismiss
   157→}
