    12→struct RoomInfoProxy: RoomInfoProxyProtocol {
    13→    let roomInfo: RoomInfo
    14→    
    15→    var id: String {
    16→        roomInfo.id
    17→    }
    18→
    19→    var creators: [String] {
    20→        roomInfo.creators ?? []
    21→    }
    22→
    23→    var displayName: String? {
    24→        roomInfo.displayName
    25→    }
    26→
    27→    var rawName: String? {
    28→        roomInfo.rawName
    29→    }
    30→
    31→    var topic: String? {
    32→        roomInfo.topic
    33→    }
    34→
    35→    /// The room's avatar URL. Use this for editing and favour ``avatar`` for display.
    36→    var avatarURL: URL? {
    37→        roomInfo.avatarUrl.flatMap(URL.init)
    38→    }
    39→
    40→    /// Here we're assuming unknown rooms are unencrypted.
    41→    /// Fortunately https://github.com/matrix-org/matrix-rust-sdk/pull/4778 makes that very much of an edge case and we
    42→    /// also automatically start a `latestEncryptionState` fetch if needed.
    43→    /// In the worst case, even if we are to assume a room is unencrypted, the SDK will still determine the correct
    44→    /// state before any message is sent.
    45→    var isEncrypted: Bool {
    46→        roomInfo.encryptionState == .encrypted
    47→    }
    48→    
    49→    var isDirect: Bool {
    50→        roomInfo.isDirect
    51→    }
    52→
    53→    var isSpace: Bool {
    54→        roomInfo.isSpace
    55→    }
    56→    
    57→    var successor: SuccessorRoom? {
    58→        roomInfo.successorRoom
    59→    }
    60→
    61→    var isFavourite: Bool {
    62→        roomInfo.isFavourite
    63→    }
    64→
    65→    var canonicalAlias: String? {
    66→        roomInfo.canonicalAlias
    67→    }
