     9→import Combine
    10→import SwiftUI
    11→
    12→typealias DeclineAndBlockScreenViewModelType = StateStoreViewModelV2<DeclineAndBlockScreenViewState, DeclineAndBlockScreenViewAction>
    13→
    14→class DeclineAndBlockScreenViewModel: DeclineAndBlockScreenViewModelType, DeclineAndBlockScreenViewModelProtocol {
    15→    let userID: String
    16→    let roomID: String
    17→    let clientProxy: ClientProxyProtocol
    18→    let userIndicatorController: UserIndicatorControllerProtocol
    19→    
    20→    private let actionsSubject: PassthroughSubject<DeclineAndBlockScreenViewModelAction, Never> = .init()
    21→    var actionsPublisher: AnyPublisher<DeclineAndBlockScreenViewModelAction, Never> {
    22→        actionsSubject.eraseToAnyPublisher()
    23→    }
    24→
    25→    init(userID: String,
    26→         roomID: String,
    27→         clientProxy: ClientProxyProtocol,
    28→         userIndicatorController: UserIndicatorControllerProtocol) {
    29→        self.userID = userID
    30→        self.roomID = roomID
    31→        self.clientProxy = clientProxy
    32→        self.userIndicatorController = userIndicatorController
    33→        super.init(initialViewState: DeclineAndBlockScreenViewState())
    34→    }
    35→    
    36→    // MARK: - Public
    37→    
    38→    override func process(viewAction: DeclineAndBlockScreenViewAction) {
    39→        MXLog.info("View model: received view action: \(viewAction)")
    40→        
    41→        switch viewAction {
    42→        case .dismiss:
    43→            actionsSubject.send(.dismiss(hasDeclined: false))
    44→        case .decline:
    45→            Task { await decline() }
    46→        }
    47→    }
    48→    
    49→    private func decline() async {
    50→        showLoadingIndicator()
    51→        guard case let .invited(roomProxy) = await clientProxy.roomForIdentifier(roomID) else {
    52→            MXLog.error("DeclineAndBlockScreenViewModel: Unable to find an invited room for identifier \(roomID)")
    53→            hideLoadingIndicator()
    54→            showTryAgainAlert { [weak self] in Task { await self?.decline() } }
    55→            return
    56→        }
    57→        
    58→        switch await roomProxy.rejectInvitation() {
    59→        case .success:
    60→            var shouldShowFailure = false
    61→            if state.bindings.shouldReport {
    62→                shouldShowFailure = await clientProxy.reportRoomForIdentifier(roomID, reason: state.bindings.reportReason).isFailure
    63→            }
    64→            
    65→            if state.bindings.shouldBlockUser {
    66→                shouldShowFailure = await clientProxy.ignoreUser(userID).isFailure
    67→            }
    68→            
    69→            hideLoadingIndicator()
    70→            if shouldShowFailure {
    71→                showError()
    72→            } else {
    73→                showSuccess()
    74→            }
    75→            actionsSubject.send(.dismiss(hasDeclined: true))
    76→        case .failure:
    77→            hideLoadingIndicator()
    78→            showTryAgainAlert { [weak self] in Task { await self?.decline() } }
    79→        }
    80→    }
    81→    
    82→    private static let loadingIndicator = "\(DeclineAndBlockScreenViewModel.self).loadingIndicator"
    83→    
    84→    private func showLoadingIndicator() {
    85→        userIndicatorController.submitIndicator(.init(id: Self.loadingIndicator,
    86→                                                      type: .modal(progress: .indeterminate,
    87→                                                                   interactiveDismissDisabled: true,
    88→                                                                   allowsInteraction: false),
    89→                                                      title: L10n.commonLoading,
    90→                                                      persistent: true))
    91→    }
    92→    
    93→    private func hideLoadingIndicator() {
    94→        userIndicatorController.retractIndicatorWithId(Self.loadingIndicator)
    95→    }
    96→    
    97→    private func showError() {
    98→        userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
    99→    }
